function simpleQuestion(subject, grade, semester, slot) {
  const row = SIMPLE_SUBJECT_BANKS[subject][slot % 10];
  return question({ grade, semester, subject, slot, topic: row[0], text: row[1], answer: row[2], distractors: row[3], explanation: row[4] });
}

