function biologyQuestion(grade, semester, slot) {
  const row = BIOLOGY_BANK[slot % 10];
  const lead = ({ 8: "დააკვირდი ბიოლოგიურ პროცესს: ", 9: "ორგანიზმის მუშაობაზე მსჯელობისას: ", 10: "სისტემურ დონეზე იმსჯელე: ", 11: "კვლევის შედეგის ახსნისას: " })[grade] ?? "";
  return question({ grade, semester, subject: "ბიოლოგია", slot, topic: row[0], text: lead + row[1], answer: row[2], distractors: row[3], explanation: row[4] });
}

