function geographyQuestion(grade, semester, slot) {
  const row = GEOGRAPHY_BANK[slot % 10];
  const text = grade >= 11 && slot === 9 ? `დაგეგმვის მაგალითი: ${row[1]}` : row[1];
  return question({ grade, semester, subject: "გეოგრაფია", slot, topic: row[0], text, answer: row[2], distractors: row[3], explanation: row[4] });
}

