function historyQuestion(grade, semester, slot) {
  const row = HISTORY_BANK[slot % 10];
  const lead = ({ 9: "ისტორიულ მაგალითზე მსჯელობისას: ", 10: "ეპოქის კონტექსტის შეფასებისას: ", 11: "წყაროს ანალიზისას: ", 12: "დამოუკიდებელი ისტორიული კვლევისას: " })[grade] ?? "";
  return question({ grade, semester, subject: "ისტორია", slot, topic: row[0], text: lead + row[1], answer: row[2], distractors: row[3], explanation: row[4] });
}

