function civicsQuestion(grade, semester, slot) {
  const row = CIVICS_BANK[slot % 10];
  const lead = ({ 7: "სასკოლო საზოგადოებაზე მსჯელობისას: ", 8: "თემის ცხოვრებაზე მსჯელობისას: ", 9: "მოქალაქის მონაწილეობის შეფასებისას: ", 10: "სახელმწიფო ინსტიტუტების განხილვისას: ", 11: "საჯარო პოლიტიკის შეფასებისას: " })[grade] ?? "";
  const text = lead + (grade === 7 && slot === 0 ? row[1].replace("დემოკრატიულ სახელმწიფოში", "სახელმწიფოში") : row[1]);
  return question({ grade, semester, subject: "მოქალაქეობა", slot, topic: row[0], text, answer: row[2], distractors: row[3], explanation: row[4] });
}

function physicsQuestion(grade, semester, slot) {
  const k = grade + semester + slot;
  const rows = [
    () => { const v = 4 + k % 5, t = 3 + k % 4; return ["სიჩქარე", `სხეული ${v} მ/წმ მუდმივი სიჩქარით ${t} წამი მოძრაობს. რა მანძილს გაივლის?`, `${v * t} მ`, [`${v + t} მ`, `${num(v / t)} მ`, `${v * t * 2} მ`], `თანაბარ მოძრაობაში s=v·t=${v}·${t}=${v * t} მეტრს.`]; },
    () => { const v0 = 2 + k % 3, v1 = v0 + 8, t = 4; return ["აჩქარება", `სიჩქარე ${v0} მ/წმ-დან ${v1} მ/წმ-მდე ${t} წამში გაიზარდა. საშუალო აჩქარებაა:`, `${num((v1 - v0) / t)} მ/წმ²`, [`${num((v1 + v0) / t)} მ/წმ²`, `${v1 - v0} მ/წმ²`, `${v1 * t} მ/წმ²`], `აჩქარება არის სიჩქარის ცვლილება გაყოფილი დროზე: (${v1}−${v0})/${t}=${num((v1 - v0) / t)} მ/წმ².`]; },
    () => { const m = 3 + k % 4, a = 2 + k % 3; return ["ნიუტონის მეორე კანონი", `მასა ${m} კგ სხეულის აჩქარებაა ${a} მ/წმ². ტოლქმედი ძალაა:`, `${m * a} ნ`, [`${m + a} ნ`, `${num(m / a)} ნ`, `${m * a * 2} ნ`], `ნიუტონის მეორე კანონით F=ma=${m}·${a}=${m * a} ნიუტონს.`]; },
    () => { const f = 5 + k % 5, s = 3 + k % 4; return ["მექანიკური მუშაობა", `მუდმივი ${f} ნ ძალა სხეულს ძალის მიმართულებით ${s} მ-ზე გადაადგილებს. შესრულებული მუშაობაა:`, `${f * s} ჯ`, [`${f + s} ჯ`, `${num(f / s)} ჯ`, `${2 * f * s} ჯ`], `ძალა და გადაადგილება თანამიმართულია, ამიტომ A=Fs=${f}·${s}=${f * s} ჯ.`]; },
    () => { const work = 60 + 10 * (k % 4), t = 5; return ["სიმძლავრე", `${work} ჯ მუშაობა ${t} წამში შესრულდა. საშუალო სიმძლავრეა:`, `${work / t} ვტ`, [`${work * t} ვტ`, `${work - t} ვტ`, `${work / (t * 2)} ვტ`], `სიმძლავრე P=A/t=${work}/${t}=${work / t} ვატია.`]; },
    () => { const force = 100 + 20 * (k % 4), area = 2; return ["წნევა", `${force} ნ ძალა თანაბრად მოქმედებს ${area} მ² ფართობზე. წნევა რამდენია?`, `${force / area} პა`, [`${force * area} პა`, `${force + area} პა`, `${force} პა`], `წნევა p=F/S=${force}/${area}=${force / area} პასკალია.`]; },
    () => { const current = 2 + k % 3, resistance = 4 + k % 4; return ["ომის კანონი", `წრედში დენის ძალაა ${current} ა, წინაღობა — ${resistance} ომი. ძაბვაა:`, `${current * resistance} ვ`, [`${num(resistance / current)} ვ`, `${current + resistance} ვ`, `${current * resistance * 2} ვ`], `ომის კანონით U=IR=${current}·${resistance}=${current * resistance} ვოლტს.`]; },
    () => { const m = 2 + k % 3, h = 5, g = 10; return ["პოტენციური ენერგია", `${m} კგ ტვირთი დედამიწის ზედაპირთან ${h} მ სიმაღლეზეა. g≈${g} მ/წმ². პოტენციური ენერგიაა:`, `${m * g * h} ჯ`, [`${m * h} ჯ`, `${g * h} ჯ`, `${m * g} ჯ`], `გრავიტაციული პოტენციური ენერგია E=mgh=${m}·${g}·${h}=${m * g * h} ჯ.`]; },
    () => { const m = 3 + k % 3, v = 2 + k % 4; return ["იმპულსი", `${m} კგ სხეული ${v} მ/წმ სიჩქარით მოძრაობს. მისი იმპულსის მოდულია:`, `${m * v} კგ·მ/წმ`, [`${m + v} კგ·მ/წმ`, `${num(m / v)} კგ·მ/წმ`, `${m * v * 2} კგ·მ/წმ`], `იმპულსის მოდულია p=mv=${m}·${v}=${m * v} კგ·მ/წმ.`]; },
    () => { const f = 5 + k % 4; const wavelength = 2; return ["ტალღა", `ტალღის სიხშირეა ${f} ჰც, ტალღის სიგრძე — ${wavelength} მ. გავრცელების სიჩქარეა:`, `${f * wavelength} მ/წმ`, [`${num(f / wavelength)} მ/წმ`, `${f + wavelength} მ/წმ`, `${f} მ/წმ`], `ტალღის სიჩქარე v=fλ=${f}·${wavelength}=${f * wavelength} მ/წმ.`]; },
  ];
  const row = rows[slot % 10]();
  return question({ grade, semester, subject: "ფიზიკა", slot, topic: row[0], text: row[1], answer: row[2], distractors: row[3], explanation: row[4] });
}

