function safetyQuestion(grade, semester, slot) {
  const row = SAFETY_BANK[slot % 10];
  return question({ grade, semester, subject: "სამოქალაქო თავდაცვა და უსაფრთხოება", slot, topic: row[0], text: row[1], answer: row[2], distractors: row[3], explanation: row[4] });
}

const BUILDERS = {
  "მათემატიკა": mathQuestion,
  "ინგლისური": englishQuestion,
  "ბუნება": (grade, semester, slot) => simpleQuestion("ბუნება", grade, semester, slot),
  "ჩვენი საქართველო": (grade, semester, slot) => simpleQuestion("ჩვენი საქართველო", grade, semester, slot),
  "ბიოლოგია": biologyQuestion,
  "გეოგრაფია": geographyQuestion,
  "ისტორია": historyQuestion,
  "მოქალაქეობა": civicsQuestion,
  "ფიზიკა": physicsQuestion,
  "ქიმია": chemistryQuestion,
  "ქართული ენა და ლიტერატურა": georgianQuestion,
  "სამოქალაქო თავდაცვა და უსაფრთხოება": safetyQuestion,
};

export const FIFTH_PAPER_EXPANSION_V3 = Object.entries(FIFTH_PAPER_EXPANSION_V3_BLUEPRINT).flatMap(([bucket, count]) => {
  const [gradeText, subject, semesterText] = bucket.split("|");
  const builder = BUILDERS[subject];
  if (!builder) throw new Error(`No fifth-paper builder for ${subject}`);
  return Array.from({ length: count }, (_, slot) => builder(Number(gradeText), Number(semesterText), slot));
});

export function validateFifthPaperExpansionV3(rows = FIFTH_PAPER_EXPANSION_V3) {
  const ids = new Set(), prompts = new Set(), conceptsByBucket = new Map(), counts = {};
  for (const item of rows) {
    const bucket = `${item.grade}|${item.subject}|${item.semester}`;
    counts[bucket] = (counts[bucket] ?? 0) + 1;
    if (!FIFTH_PAPER_EXPANSION_V3_BLUEPRINT[bucket]) throw new Error(`Unsupported fifth-paper bucket: ${bucket}`);
    if (!item.id || ids.has(item.id)) throw new Error(`Duplicate or empty fifth-paper id: ${item.id}`);
    ids.add(item.id);
    const prompt = `${bucket}|${normalize(item.text)}`;
    if (prompts.has(prompt)) throw new Error(`Duplicate fifth-paper prompt: ${item.id}`);
    prompts.add(prompt);
    if (!Array.isArray(item.options) || item.options.length !== 4 || item.options.some(option => !String(option).trim()) || new Set(item.options.map(normalize)).size !== 4) throw new Error(`Invalid fifth-paper options: ${item.id}`);
    if (!Number.isInteger(item.correct) || item.correct < 0 || item.correct >= 4) throw new Error(`Invalid fifth-paper answer: ${item.id}`);
    if (!String(item.explanation).trim() || String(item.explanation).trim().length < 30 || /<[^>]+>/u.test(item.explanation)) throw new Error(`Invalid fifth-paper explanation: ${item.id}`);
    if (!String(item.text).trim() || String(item.text).trim().length < 20 || /<[^>]+>/u.test(item.text)) throw new Error(`Invalid fifth-paper prompt: ${item.id}`);
    if (!conceptsByBucket.has(bucket)) conceptsByBucket.set(bucket, new Set());
    if (conceptsByBucket.get(bucket).has(item.concept)) throw new Error(`Repeated fifth-paper concept in ${bucket}: ${item.concept}`);
    conceptsByBucket.get(bucket).add(item.concept);
  }
  for (const [bucket, expected] of Object.entries(FIFTH_PAPER_EXPANSION_V3_BLUEPRINT)) {
    if ((counts[bucket] ?? 0) !== expected) throw new Error(`Fifth-paper coverage mismatch for ${bucket}: ${counts[bucket] ?? 0}/${expected}`);
  }
  return { questions: rows.length, buckets: Object.keys(counts).length, counts };
}

validateFifthPaperExpansionV3();
